def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            filled = set(cells)

            # A hollow object has an empty cell inside its bounding box
            # that cannot reach the bounding-box boundary.
            empty = {(y, x) for y in range(r0, r1 + 1)
                              for x in range(c0, c1 + 1)
                              if (y, x) not in filled}
            hole = False
            while empty:
                start = next(iter(empty))
                todo = [start]
                empty.remove(start)
                touches_edge = False
                while todo:
                    y, x = todo.pop()
                    if y in (r0, r1) or x in (c0, c1):
                        touches_edge = True
                    for p in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                        if p in empty:
                            empty.remove(p)
                            todo.append(p)
                if not touches_edge:
                    hole = True

            objects.append({
                "top_group": hole,
                "r0": r0,
                "r1": r1,
                "shape": [(y-r0, x, color) for y, x in cells],
            })

    out = [[0] * w for _ in range(h)]
    occupied = set()

    # Settle hollow objects upward and non-hollow objects downward.
    for top_group in (True, False):
        group = [o for o in objects if o["top_group"] == top_group]
        group.sort(key=lambda o: o["r0"] if top_group else -o["r1"])

        for obj in group:
            shape = obj["shape"]
            height = obj["r1"] - obj["r0"] + 1
            starts = range(0, h - height + 1) if top_group else range(h - height, -1, -1)
            for start in starts:
                points = [(start + dy, x) for dy, x, _ in shape]
                if all(p not in occupied for p in points):
                    for (y, x), (_, _, color) in zip(points, shape):
                        out[y][x] = color
                        occupied.add((y, x))
                    break

    return out
